  String translate(String key) {
    return _localizedValues[locale.languageCode]?[key] ?? key;
  }

  /// Every key one bundle defines.
  ///
  /// Exists for the tests that compare bundles against each other. A key
  /// missing from a bundle does not fall back to English - [translate]
  /// returns the key itself, and the ticket builder prints whatever it is
  /// handed, so a gap shows up as `order_code` on a customer's receipt.
  static Iterable<String> keysFor(String languageCode) =>
      _localizedValues[languageCode]?.keys ?? const <String>[];

  // Convenience getters
  String get appTitle => translate('app_title');
  String get ok => translate('ok');
  String get cancel => translate('cancel');
  String get close => translate('close');
  String get save => translate('save');
  String get delete => translate('delete');
  String get edit => translate('edit');
  String get add => translate('add');
  String get search => translate('search');
  String get refresh => translate('refresh');
  String get loading => translate('loading');
  String get error => translate('error');
  String get success => translate('success');
}

class _AppLocalizationsDelegate extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) {
    return ['en', 'ar', 'fr', 'es'].contains(locale.languageCode);
  }

  @override
  Future<AppLocalizations> load(Locale locale) async {
    return AppLocalizations(locale);
  }

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}

